#!/usr/bin/env node
// Builds "Anatomical 3D Model/lang/la/names.js" (the Latin pack) from the Latin name lists in lang/latin/data/.
// Usage: node scripts/build_la_pack.js
// names.js embeds names.txt, structures.txt and directions.txt, so edit those files and run this script again. Do not edit la/names.js by hand.
// The page shell (language switch, styles, window.__zh) is copied from lang/es/names.js, from "const cache" to the end, so all packs share one switch.
const fs = require('fs'), path = require('path');
const lang = path.join(__dirname, '..', 'Anatomical 3D Model', 'lang');
const read = (...p) => fs.readFileSync(path.join(lang, ...p), 'utf8');
const data = f => read('latin', 'data', f).split('\n').filter(l => l.trim() && l[0] !== '#').join('\n');

const es = read('es', 'names.js');
const i = es.indexOf('  const cache = new Map();');
if (i < 0) { console.error('lang/es/names.js has no "const cache" marker'); process.exit(1); }
let shell = es.slice(i)
  .replace("const PACK = 'es'", "const PACK = 'la'")
  .replace('Chinese labels are on only', 'Latin labels are on only')
  .replace("'zh-Hant', 'zh-Hans' or 'en'", "'zh-Hant', 'zh-Hans', 'es', 'la' or 'en'")
  .replace(/the Chinese name/g, 'the Latin name').replace(/no Chinese name/g, 'no Latin name')
  .replace('Choosing the other Chinese pack', 'Choosing another pack')
  .replace('.zh{display:none;', '.zh{display:none;font-style:italic;')
  .replace('[data-zh]::after{content:" " attr(data-zh);', '[data-zh]::after{content:" " attr(data-zh);font-style:italic;');
// tag() marks the Latin name lang="la"
shell = shell.replace(/(tag: en => \{[^\n]*lang=")' \+ PACK \+ '"/, '$1la"');

const out = `// Latin (Latina) labels. Every structure name shows its Latin name (Terminologia Anatomica style) beside the English one, in italics.
// GENERATED by scripts/build_la_pack.js from lang/latin/data/names.txt, structures.txt and directions.txt. Edit those files and run the script again.
// Names are built by lang/latin/compose.js (loaded first by index.js): exact entry, else direction words plus one structure, with sides in Latin
// (Ren sinister), Roman numerals for ribs and vertebrae, and codes kept. A label with no Latin name shows in English only.
(function () {
  const C = window.__latinCompose;
  const L = C && C.create({
    names: \`
${data('names.txt')}
\`,
    structures: \`
${data('structures.txt')}
\`,
    directions: \`
${data('directions.txt')}
\`,
  });
  const tr = s => (L ? L.latinName(s) : null);

${shell}`;
fs.writeFileSync(path.join(lang, 'la', 'names.js'), out);
console.log('la/names.js', out.split('\n').length, 'lines');
